<script setup>
import { computed } from 'vue'
import { useRouter } from 'vue-router'
import { groupById, packageById, save, state } from '../stores/lexigo'
const props = defineProps({ id: String }); const router = useRouter(); const pkg = computed(() => packageById(props.id)); const speak = (term) => { if (state.sound && 'speechSynthesis' in window) speechSynthesis.speak(new SpeechSynthesisUtterance(term)) }; const remove = () => { if (confirm(`Delete “${pkg.value.name}”?`)) { state.packages = state.packages.filter((item) => item.id !== pkg.value.id); save(); router.push('/library') } }
</script>
<template><section v-if="pkg" class="mx-auto max-w-5xl px-5 py-14"><RouterLink to="/library" class="text-sm font-bold text-slate-500">← Vocabulary library</RouterLink><div class="mt-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><span class="rounded-full bg-violet-100 px-2 py-1 text-[11px] font-bold text-lexi">{{ groupById(pkg.groupId)?.name || 'Unassigned' }}</span><h1 class="mt-3 font-display text-5xl font-bold">{{ pkg.name }}</h1><p class="mt-2 text-slate-500">{{ pkg.words.length }} words in this package</p></div><div><RouterLink :to="`/practice/${pkg.id}`" class="rounded-xl bg-lexi px-4 py-3 text-sm font-bold text-white">Start practice →</RouterLink><button class="ml-3 text-sm font-bold text-rose-600" @click="remove">Delete</button></div></div><div class="mt-8 grid gap-3"><article v-for="(word, index) in pkg.words" :key="word.term" class="flex gap-5 rounded-2xl border border-slate-200 bg-white p-5"><span class="font-display text-lg font-bold text-violet-300">{{ String(index + 1).padStart(2, '0') }}</span><div><h2 class="font-display text-2xl font-bold">{{ word.term }} <small class="font-sans text-sm font-normal text-slate-400">{{ word.pronunciation }}</small></h2><p class="mt-1 font-bold text-lexi">{{ word.meaning || 'Add a meaning' }}</p><p v-if="word.example" class="mt-1 text-sm italic text-slate-500">“{{ word.example }}”</p></div><button class="ml-auto self-center rounded-lg bg-violet-50 p-2" @click="speak(word.term)">🔊</button></article></div></section><section v-else class="mx-auto max-w-5xl px-5 py-14">Package not found.</section></template>
